j=j.replace('return [65,15,115]','return [-65,15,115]').replace('return [40,-45,30]','return [-40,-45,30]').replace('return [75,0,30]','return [-75,0,30]').replace('return [110,0,30]','return [-110,0,30]').replace('return [145,0,35]','return [-85,0,35]')
j=j.replace("n.includes('cover')","n.includes('removable_plug_cap')").replace("p.name.includes('adjustment_cover')","p.name.includes('removable_plug_cap')")
j=j.replace("home:[[650,800,470],[185,35,145]]","home:[[-300,800,470],[170,35,145]]").replace("plug:[[570,220,210],[378,0,125]]","plug:[[-190,190,165],[-12,3,115]]")
j=j.replace('Curved exhaust plenum with integrated fixed guide and open intake ribs. The exploded view separates the two body halves.','The plenum wall is the laptop backrest. A profiled hinge-end seat is integrated into each half; the underside intake remains unobstructed.')
j=j.replace('Removable cover over the plug adjustment station. Toggle it off to inspect the adjustment stages.','Removable cap of the compact plug cassette. Shims set height; two broad shelf slots allow lateral and insertion calibration before locking.')
j=j.replace('Lift / lower along the guides','Lift / lower onto the seats').replace('The closed envelope is simplified; the heel contacts are derived from Dell mesh sections.','The two Thunderbolt ports are on the keyboard-left end (screen-right in Lid view). The opposite USB-C port is not Thunderbolt. Source mesh dimensions are approximate.')
j=j.replace("n.startsWith('X_')?'Insertion-depth adjustment and locking hardware: ±5 mm nominal range.'", "n.startsWith('X_')?'Two-piece plug cassette: shim height and slide in the shelf slots, then lock the two mounting screws.'")
j=j.replace("if(n.includes('seal')||n.includes('corner_pad'))", "if(n.includes('lid_bearing'))return [0,-28,0];if(n.includes('seal')||n.includes('corner_pad'))")
