j=j.replace("for(const x of [84,270])", "for(const x of [84,269.68])")
# Give the viewer a reproducible camera-coordinate audit, shared by both renderers.
j += '''\nwindow.deskDockOrientation=()=>{const c=new THREE.PerspectiveCamera(36,1,1,4000);c.up.set(0,0,1);c.position.set(177,930,240);c.lookAt(177,30,155);c.updateMatrixWorld();const left=new THREE.Vector3(0,0,120).project(c),right=new THREE.Vector3(353.68,0,120).project(c);return {revision:'D6',keyboardLeftScreenX:left.x,keyboardRightScreenX:right.x,keyboardLeftAppearsOnRight:left.x>right.x,withdrawalX:18};};\n'''
